// Model card page from /api/model-card (results/model_card.json, generated by scripts/build_docs.py).
import { pickSource } from './data.js';
import { el, mountNav } from './nav.js';
import { icon, reveal } from './ui.js';

mountNav('model-card.html');
const ICON = { 'Intended use': 'target', Model: 'cube', Data: 'folder', 'Per-group results': 'chart', 'Software checks': 'check', Limitations: 'info', Disclaimer: 'shield' };
const slug = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-');
// values that report something missing or not done
const WARN = /^(no\b|not run|none|unknown)|not available|\(no /i;

function value(v) {
  const s = String(v);
  if (/^\{.*\}$/.test(s)) {
    try {
      const o = JSON.parse(s), box = el('div', { class: 'jsonkv' });
      for (const [k, x] of Object.entries(o)) { const sp = el('span', {}, k.replace(/_/g, ' ') + ' '); sp.append(el('b', {}, Array.isArray(x) ? x.join(' × ') : String(x))); box.append(sp); }
      return box;
    } catch (_) { /* plain text */ }
  }
  return document.createTextNode(s);
}

function section(title, body, i) {
  const h = el('h2', { html: icon(ICON[title] || 'doc', 16) }, title);
  const s = el('section', { class: 'card mc-sec', id: slug(title), 'data-reveal': '', style: `--i:${Math.min(i, 3)}` }, h);
  if (Array.isArray(body)) { const ul = el('ul'); for (const b of body) ul.append(el('li', {}, b)); s.append(ul); }
  else if (body && typeof body === 'object') {
    const dl = el('dl', { class: 'mc-kv' });
    for (const [k, v] of Object.entries(body)) { const dd = el('dd', WARN.test(String(v)) ? { class: 'warn' } : {}); dd.append(value(v)); dl.append(el('dt', {}, k), dd); }
    s.append(dl);
  } else {
    const txt = body ?? 'Not run.';
    if (/^not run/i.test(txt)) s.append(el('p', { class: 'notrun' }, txt));
    else s.append(el('p', { class: 'mc-text' }, txt));
  }
  return s;
}

async function init() {
  const c = await pickSource().modelCard().catch(() => ({ status: 'not run' }));
  const host = document.getElementById('card'), toc = document.getElementById('toc');
  if (c.status === 'not run' || !c.sections) { host.append(el('p', { class: 'notrun' }, 'The model card has not been generated. Run `make docs`.')); toc.hidden = true; window.__ready = true; return; }
  c.sections.forEach((s, i) => {
    host.append(section(s.title, s.body, i));
    toc.append(el('a', { href: '#' + slug(s.title) }, s.title));
  });
  reveal(host);
  const links = [...toc.querySelectorAll('a')];
  const io = new IntersectionObserver(es => {
    for (const e of es) if (e.isIntersecting) for (const a of links) a.classList.toggle('on', a.getAttribute('href') === '#' + e.target.id);
  }, { rootMargin: '-30% 0px -60% 0px' });
  for (const s of host.querySelectorAll('section')) io.observe(s);
  if (links[0]) links[0].classList.add('on');
  window.__ready = true;
}
init();
